content.content:
openapi: 3.1.0
info:
  title: Team Notes API
  version: 0.3.0-teams
  description: |
    Notes shared within small teams. Each note belongs to exactly one team, and every
    member of that team can read and edit it.

    * **Auth:** every endpoint except `/health` needs `Authorization: Bearer <token>`.
    * **Visibility:** a resource outside the caller's teams is answered with `404`, never `403`,
      so the API does not reveal whether it exists (ADR-0001).
    * **Errors:** every error is an RFC 9457 `application/problem+json` document. Precedence:
      401 → 404 → 403 → 415 → 413 → 400 → 422 → 409 → 428 → 412 (NOTES-TECH-ERR-2/5, ADR-0003/0006).
    * **Concurrency:** every single-note response carries `ETag: "<version>"`. PATCH requires a matching
      `If-Match`: a missing header or `*` gets 428, a stale one gets 412 (ADR-0002).
    * **Deletion:** DELETE is soft and idempotent. `POST /notes/{id}/restore` undoes it, and `?archived=true` lists the trash.
    * **Source of truth:** behavior is pinned down by `spec/acceptance-criteria.md` and checked by `conformance/`.
servers:
  - url: http://localhost:3001
security:
  - bearer: []

paths:
  /health:
    get:
      operationId: getHealth
      security: []
      responses:
        '200':
          description: Service is up
          content:
            application/json:
              schema:
                type: object
                required: [status]
                properties:
                  status: { const: ok }

  /me:
    get:
      operationId: getMe
      responses:
        '200':
          description: The caller
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Me' }
        '401': { $ref: '#/components/responses/Unauthorized' }

  /teams:
    get:
      operationId: listMyTeams
      responses:
        '200':
          description: Teams the caller belongs to
          content:
            application/json:
              schema:
                type: object
                required: [items]
                properties:
                  items:
                    type: array
                    items: { $ref: '#/components/schemas/Team' }
        '401': { $ref: '#/components/responses/Unauthorized' }

    post:
      operationId: createTeam
      description: Create a team; the caller becomes its owner (NOTES-FUNC-TEAM-2).
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: '#/components/schemas/TeamCreate' }
      responses:
        '201':
          description: Created
          headers:
            Location: { schema: { type: string }, description: '/teams/{id}' }
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Team' }
        '400': { $ref: '#/components/responses/BadRequest' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '409': { $ref: '#/components/responses/Conflict' }
        '413': { $ref: '#/components/responses/PayloadTooLarge' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }
        '422': { $ref: '#/components/responses/Unprocessable' }

  /teams/{teamId}:
    parameters:
      - $ref: '#/components/parameters/TeamId'
    get:
      operationId: getTeam
      responses:
        '200':
          description: The team, with the caller's role
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Team' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }

  /teams/{teamId}/members:
    parameters:
      - $ref: '#/components/parameters/TeamId'
    get:
      operationId: listMembers
      responses:
        '200':
          description: Team roster
          content:
            application/json:
              schema:
                type: object
                additionalProperties: false
                required: [items]
                properties:
                  items:
                    type: array
                    items: { $ref: '#/components/schemas/Member' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }

  /teams/{teamId}/members/{userId}:
    parameters:
      - $ref: '#/components/parameters/TeamId'
      - name: userId
        in: path
        required: true
        schema: { type: string, minLength: 1, maxLength: 64 }
    put:
      operationId: addMember
      description: Owner only. Idempotent.
      responses:
        '200':
          description: The member
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Member' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '403': { $ref: '#/components/responses/Forbidden' }
        '404': { $ref: '#/components/responses/NotFound' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }
        '422': { $ref: '#/components/responses/Unprocessable' }
    delete:
      operationId: removeMember
      description: Owner only. Idempotent. Removing the last owner gets 409.
      responses:
        '204': { description: Removed }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '403': { $ref: '#/components/responses/Forbidden' }
        '404': { $ref: '#/components/responses/NotFound' }
        '409': { $ref: '#/components/responses/Conflict' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }

  /teams/{teamId}/notes:
    parameters:
      - $ref: '#/components/parameters/TeamId'
    get:
      operationId: listTeamNotes
      description: The team's live notes, newest first. With `archived=true`, only deleted notes (trash).
      parameters:
        - name: archived
          in: query
          required: false
          schema: { type: string, enum: ['true', 'false'], default: 'false' }
      responses:
        '200':
          description: The team's notes
          content:
            application/json:
              schema: { $ref: '#/components/schemas/NoteList' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
        '422': { $ref: '#/components/responses/Unprocessable' }
    post:
      operationId: createNote
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: '#/components/schemas/NoteCreate' }
      responses:
        '201':
          description: Created
          headers:
            ETag: { $ref: '#/components/headers/ETag' }
            Location:
              schema: { type: string }
              description: /notes/{id}
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Note' }
        '400': { $ref: '#/components/responses/BadRequest' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
        '413': { $ref: '#/components/responses/PayloadTooLarge' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }
        '422': { $ref: '#/components/responses/Unprocessable' }

  /notes/{noteId}:
    parameters:
      - $ref: '#/components/parameters/NoteId'
    get:
      operationId: getNote
      responses:
        '200':
          description: The note
          headers:
            ETag: { $ref: '#/components/headers/ETag' }
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Note' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }
    patch:
      operationId: updateNote
      description: A partial update. Only the fields present change, and `version` increments by one.
      parameters:
        - name: If-Match
          in: header
          required: true
          description: The note's current ETag, e.g. `"3"`. Missing or `*` gets 428.
          schema: { type: string }
      requestBody:
        required: true
        content:
          application/json:
            schema: { $ref: '#/components/schemas/NotePatch' }
      responses:
        '200':
          description: Updated
          headers:
            ETag: { $ref: '#/components/headers/ETag' }
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Note' }
        '400': { $ref: '#/components/responses/BadRequest' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
        '412': { $ref: '#/components/responses/PreconditionFailed' }
        '413': { $ref: '#/components/responses/PayloadTooLarge' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }
        '422': { $ref: '#/components/responses/Unprocessable' }
        '428': { $ref: '#/components/responses/PreconditionRequired' }
    delete:
      operationId: deleteNote
      description: Soft delete. Idempotent; deleting an already-deleted note also returns 204.
      responses:
        '204': { description: Deleted }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }

  /notes/{noteId}/restore:
    parameters:
      - $ref: '#/components/parameters/NoteId'
    post:
      operationId: restoreNote
      description: Undo a soft delete (version + 1). Restoring a live note is a no-op 200.
      responses:
        '200':
          description: The restored note
          headers:
            ETag: { $ref: '#/components/headers/ETag' }
          content:
            application/json:
              schema: { $ref: '#/components/schemas/Note' }
        '401': { $ref: '#/components/responses/Unauthorized' }
        '404': { $ref: '#/components/responses/NotFound' }
        '415': { $ref: '#/components/responses/UnsupportedMediaType' }

components:
  securitySchemes:
    bearer:
      type: http
      scheme: bearer

  parameters:
    TeamId:
      name: teamId
      in: path
      required: true
      schema: { type: string, minLength: 1, maxLength: 64 }
    NoteId:
      name: noteId
      in: path
      required: true
      schema: { type: string, minLength: 1, maxLength: 64 }

  headers:
    ETag:
      description: Strong ETag carrying the note's version, e.g. `"3"`.
      schema: { type: string, pattern: '^"[0-9]+"$' }

  responses:
    Forbidden:
      description: A member, but not allowed (e.g. not the owner)
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    Conflict:
      description: Conflicts with current state (taken id, last owner)
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    PreconditionFailed:
      description: If-Match does not match the current version
      headers:
        ETag: { $ref: '#/components/headers/ETag' }
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    PreconditionRequired:
      description: If-Match missing (or `*`)
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    UnsupportedMediaType:
      description: Request body is not application/json
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    BadRequest:
      description: Malformed request (e.g. invalid JSON)
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    Unauthorized:
      description: Missing or invalid bearer token
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    NotFound:
      description: Not found, or not visible to the caller
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    PayloadTooLarge:
      description: Request body exceeds 2 MiB
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/Problem' }
    Unprocessable:
      description: Validation failed
      content:
        application/problem+json:
          schema: { $ref: '#/components/schemas/ValidationProblem' }

  schemas:
    Problem:
      type: object
      required: [type, title, status]
      properties:
        type: { type: string }
        title: { type: string }
        status: { type: integer, minimum: 400, maximum: 599 }
        detail: { type: string }
        instance: { type: string }

    ValidationProblem:
      allOf:
        - $ref: '#/components/schemas/Problem'
        - type: object
          required: [errors]
          properties:
            errors:
              type: array
              minItems: 1
              items:
                type: object
                required: [field, message]
                properties:
                  field: { type: string }
                  message: { type: string }

    Team:
      type: object
      additionalProperties: false
      required: [id, name, role]
      properties:
        id: { type: string }
        name: { type: string }
        role: { enum: [owner, member] }

    TeamCreate:
      type: object
      additionalProperties: false
      required: [id, name]
      properties:
        id: { type: string, pattern: '^[a-z0-9-]{3,40}$' }
        name: { type: string, minLength: 1, maxLength: 80 }

    Member:
      type: object
      additionalProperties: false
      required: [id, name, role]
      properties:
        id: { type: string }
        name: { type: string }
        role: { enum: [owner, member] }

    Me:
      type: object
      additionalProperties: false
      required: [id, name, teams]
      properties:
        id: { type: string }
        name: { type: string }
        teams:
          type: array
          items: { $ref: '#/components/schemas/Team' }

    Note:
      type: object
      additionalProperties: false
      required: [id, teamId, authorId, title, body, version, createdAt, updatedAt]
      properties:
        id: { type: string, format: uuid }
        teamId: { type: string }
        authorId: { type: string }
        title: { type: string, minLength: 1, maxLength: 200 }
        body: { type: string, maxLength: 100000 }
        version: { type: integer, minimum: 1 }
        createdAt: { type: string, format: date-time }
        updatedAt: { type: string, format: date-time }
        deletedAt: { type: string, format: date-time, description: Present only on deleted notes. }

    NoteList:
      type: object
      additionalProperties: false
      required: [items]
      properties:
        items:
          type: array
          items: { $ref: '#/components/schemas/Note' }

    NoteCreate:
      type: object
      additionalProperties: false
      required: [title]
      properties:
        title: { type: string, minLength: 1, maxLength: 200, description: 'Trimmed and stored trimmed; length in Unicode code points.' }
        body: { type: string, maxLength: 100000, default: '' }

    NotePatch:
      type: object
      additionalProperties: false
      minProperties: 1
      properties:
        title: { type: string, minLength: 1, maxLength: 200 }
        body: { type: string, maxLength: 100000 }
#!/usr/bin/env node
// Conformance runner. It runs the data-only cases in cases.json against any backend at BASE_URL
// and validates every response against spec/openapi.yaml.
//
//   BASE_URL=http://localhost:3001 node conformance/run.mjs [--only <alias-or-case-prefix>] [--json out.json] [--strict]
//   node conformance/run.mjs --check     # self-check cases.json against the AC file; no server needed
//
// --strict also fails when a ratified AC has no case ("unverified"). Draft ACs are reported but not required.
//
// Step extras: rawBodyBase64 (exact bytes, e.g. invalid UTF-8), noContract (skip OpenAPI validation, e.g. unknown routes), parallel: N + expectCounts {status: n}.
// It exits 0 only if every case passes. Each case names the AC it falsifies. A failing case refutes that AC.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import Ajv2020 from 'ajv/dist/2020.js';
import addFormats from 'ajv-formats';
import YAML from 'yaml';

const here = dirname(fileURLToPath(import.meta.url));
const BASE_URL = (process.env.BASE_URL ?? 'http://localhost:3001').replace(/\/$/, '');
const args = process.argv.slice(2);
const only = args.includes('--only') ? args[args.indexOf('--only') + 1] : null;
const jsonOut = args.includes('--json') ? args[args.indexOf('--json') + 1] : null;

const strict = args.includes('--strict');
const spec = YAML.parse(readFileSync(join(here, '../spec/openapi.yaml'), 'utf8'));
const { cases, tokens } = JSON.parse(readFileSync(join(here, 'cases.json'), 'utf8'));

// ---- AC catalogue: every card heading, and whether its tier is ratified ------------------------
const acText = readFileSync(join(here, '../spec/acceptance-criteria.md'), 'utf8');
const ratifiedTiers = (acText.match(/^ratified_tiers:\s*"([^"]*)"/m)?.[1] ?? '').split(',').map((t) => t.trim()).filter(Boolean);
const catalogue = {};
let tier = null;
for (const line of acText.split('\n')) {
  const t = line.match(/^## Tier (\d+)/); if (t) tier = t[1];
  const h = line.match(/^#### (NOTES-[A-Z]+-[A-Z]+-\d+)/);
  if (h) catalogue[h[1]] = { tier, ratified: ratifiedTiers.includes(tier) };
}

if (args.includes('--check')) {
  const problems = [];
  const ids = new Set();
  for (const c of cases) {
    if (ids.has(c.id)) problems.push(`duplicate case id ${c.id}`);
    ids.add(c.id);
    if (!catalogue[c.falsifies]) problems.push(`${c.id}: falsifies unknown AC ${c.falsifies}`);
    for (const [i, st] of (c.steps ?? []).entries())
      if (st.expect?.status === undefined && !st.expectCounts) problems.push(`${c.id} step ${i + 1}: no expect.status`);
  }
  const covered = new Set(cases.map((c) => c.falsifies));
  for (const [ac, meta] of Object.entries(catalogue))
    if (!covered.has(ac)) (meta.ratified ? problems : console.log(`note: draft AC ${ac} has no case yet`), meta.ratified && problems.push(`ratified AC ${ac} has no case`));
  for (const p of problems) console.log(`CHECK ${p}`);
  console.log(`check: ${cases.length} cases, ${Object.keys(catalogue).length} ACs (ratified tiers: ${ratifiedTiers.join(',') || 'none'}), ${problems.length} problems`);
  process.exit(problems.length ? 1 : 0);
}

// ---- OpenAPI response validation -------------------------------------------------------------
const ajv = new Ajv2020({ strict: false, allErrors: true });
addFormats(ajv);
ajv.addSchema({ $id: 'spec', components: spec.components });
const rewriteRefs = (node) =>
  JSON.parse(JSON.stringify(node).replaceAll('"#/components/', '"spec#/components/'));

const operations = Object.entries(spec.paths).flatMap(([template, item]) =>
  ['get', 'post', 'put', 'patch', 'delete'].filter((m) => item[m]).map((m) => ({
    method: m.toUpperCase(),
    regex: new RegExp('^' + template.replace(/\{[^}]+\}/g, '[^/]+') + '$'),
    op: item[m],
  })));

function resolveResponse(resp) {
  if (resp?.$ref) return resp.$ref.split('/').slice(1).reduce((o, k) => o[k], spec);
  return resp;
}

function validateAgainstSpec(method, path, status, contentType, body) {
  const pathOnly = path.split('?')[0];
  const match = operations.find((o) => o.method === method && o.regex.test(pathOnly));
  if (!match) return `no operation in spec for ${method} ${pathOnly}`;
  const resp = resolveResponse(match.op.responses[String(status)]);
  if (!resp) return `status ${status} not declared for ${match.op.operationId}`;
  if (!resp.content) return body === null ? null : `${match.op.operationId} ${status} declares no body`;
  const mediaType = (contentType ?? '').split(';')[0].trim();
  const media = resp.content[mediaType];
  if (!media) return `content-type '${mediaType}' not declared for ${match.op.operationId} ${status}`;
  const validate = ajv.compile(rewriteRefs(media.schema));
  return validate(body) ? null : `schema: ${ajv.errorsText(validate.errors)}`;
}

// ---- Case execution ----------------------------------------------------------------------------
const interpolate = (value, vars) => {
  if (typeof value === 'string') {
    const whole = value.match(/^\$\{([^}]+)\}$/);
    if (whole) return lookup(vars, whole[1]);
    return value.replace(/\$\{([^}]+)\}/g, (_, p) => String(lookup(vars, p)));
  }
  if (Array.isArray(value)) return value.map((v) => interpolate(v, vars));
  if (value && typeof value === 'object')
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, interpolate(v, vars)]));
  return value;
};
const lookup = (vars, path) => path.split('.').reduce((o, k) => o?.[k], vars);
const repeat = (s) => s.replace(/<repeat:(\d+):(.)>/gu, (_, n, ch) => ch.repeat(Number(n)));

function subsetMismatch(expected, actual, at = '$') {
  if (Array.isArray(expected)) {
    // Each expected element must subset-match some element of the actual array.
    if (!Array.isArray(actual)) return `${at}: expected array, got ${JSON.stringify(actual)}`;
    for (const [i, e] of expected.entries())
      if (!actual.some((a) => subsetMismatch(e, a) === null)) return `${at}[${i}]: no element matches ${JSON.stringify(e)}`;
    return null;
  }
  if (expected && typeof expected === 'object') {
    if (!actual || typeof actual !== 'object') return `${at}: expected object, got ${JSON.stringify(actual)}`;
    for (const [k, v] of Object.entries(expected)) {
      const m = subsetMismatch(v, actual[k], `${at}.${k}`);
      if (m) return m;
    }
    return null;
  }
  return JSON.stringify(expected) === JSON.stringify(actual)
    ? null : `${at}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`;
}

async function runStep(step, vars) {
  if (step.parallel) {
    // Fire N identical requests at once; check the status distribution (e.g. exactly one 200 under contention).
    const single = { ...step, parallel: undefined, expect: {}, save: undefined };
    const statuses = await Promise.all(Array.from({ length: step.parallel }, () => runStepStatus(single, vars)));
    const counts = {};
    for (const st of statuses) counts[st] = (counts[st] ?? 0) + 1;
    const want = interpolate(step.expectCounts ?? {}, vars);
    return JSON.stringify(Object.fromEntries(Object.entries(counts).sort())) === JSON.stringify(Object.fromEntries(Object.entries(want).sort()))
      ? [] : [`parallel x${step.parallel}: expected status counts ${JSON.stringify(want)}, got ${JSON.stringify(counts)}`];
  }
  return runOne(step, vars);
}

async function runStepStatus(step, vars) {
  const box = {};
  await runOne({ ...step, _status: box }, vars);
  return box.status;
}

async function runOne(step, vars) {
  const headers = { ...interpolate(step.headers ?? {}, vars) };
  const token = step.token ?? (step.as ? tokens[step.as] : null);
  if (token) headers.authorization = `Bearer ${token}`;
  let body;

